<script setup lang="ts">
import '../styles/workspaces.css'
import StatusIndicator from '../components/StatusIndicator.vue'
import cytoscape, { type Core, type ElementDefinition } from 'cytoscape'
import { computed, nextTick, onBeforeUnmount, onMounted, ref, shallowRef, watch } from 'vue'
import { RouterLink } from 'vue-router'
import { useRoute, useRouter } from 'vue-router'
import { graphApi, type GraphEdge, type GraphMeta, type GraphNode, type GraphPage } from '../graph/api'
import { GraphState, matchesContext, type PageContext } from '../graph/state'
import { reactive } from 'vue'
import { useAccount } from '../stores/account'
let graphResize:ResizeObserver|null=null,resizeFrame=0
const account=useAccount()
const filtersOpen=ref(false),inspectorOpen=ref(false),mobileView=ref(window.innerWidth<=700)
function drawerKeys(event:KeyboardEvent){if(!mobileView.value)return;if(event.key==='Escape'){filtersOpen.value=false;inspectorOpen.value=false;return}if(event.key!=='Tab')return;const nodes=[...(event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not(:disabled),a[href],select,input,summary')].filter(e=>e.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
watch([filtersOpen,inspectorOpen],async(open,old)=>{if(!mobileView.value)return;await nextTick();if(open[1])document.querySelector<HTMLElement>('#kg-inspector button')?.focus();else if(open[0])document.querySelector<HTMLElement>('#kg-filters button')?.focus();else if(old[1])document.getElementById('kg-inspector-toggle')?.focus();else document.getElementById('kg-filters-toggle')?.focus()})
const admin = ref(false), meta = ref<GraphMeta | null>(null), query = ref(''), results = ref<GraphNode[]>([]), selected = ref<GraphNode | null>(null)
const graphEl = ref<HTMLElement | null>(null), cy = shallowRef<Core | null>(null), loading = ref(false), error = ref(''), notice = ref(''), searchCursor = ref<string|null>(null), neighborCursor = ref<string|null>(null), searchMore = ref(false), neighborMore = ref(false), expanded = ref(false), selectedEdge = ref<GraphEdge|null>(null)
const typeFilter = ref(''), relationFilter = ref(''), verifyFilter = ref(''), publicationFilter = ref('')
const graph = reactive(new GraphState()); const nodeMap=graph.nodes, edgeMap=graph.edges; let epoch=0, metaEpoch=0, expansionSeq=0; let searchContext:PageContext={kind:'search',query:''}; let neighborContext:PageContext|null=null
const route = useRoute(), router = useRouter()
const nodeTypes = computed(() => meta.value?.nodeTypes ?? ['PLANT','TAXON','NAME','SOURCE','FILE','SAMPLE','MEASUREMENT','MORPHOLOGY','TAXONOMY','TRAIT']), relationTypes = computed(() => meta.value?.relationTypes ?? ['SOURCE_FILE','IDENTITY_REFERENCE','PARENT_TAXON','HAS_NAME','SOURCED_FROM','HAS_MEASUREMENT','SUPPORTED_BY','HAS_TRAIT','ACCEPTED_TAXON','SOURCE_NAME_RECORD'])
const scientificReferences=computed(()=>(selected.value?.sourceReference||[]).filter(ref=>/^[a-f0-9]{64}$/.test(String(ref.sourceId))))
const allNodes = () => [...nodeMap.values()]
const visibleNodes = computed(() => allNodes().filter(n=>graph.seeds.has(n.id)||((!typeFilter.value||n.nodeType===typeFilter.value)&&(!verifyFilter.value||n.verificationState===verifyFilter.value)&&(!publicationFilter.value||n.publicationState===publicationFilter.value))))
const visibleEdges = computed(() => {const ids=new Set(visibleNodes.value.map(n=>n.id));return [...edgeMap.values()].filter(e=>ids.has(e.source)&&ids.has(e.target)&&(!relationFilter.value||e.relationType===relationFilter.value)&&(!verifyFilter.value||e.verificationState===verifyFilter.value)&&(!publicationFilter.value||e.publicationState===publicationFilter.value))})
function applyGraph() {
 if (!cy.value) return
 cy.value.resize()
 const visible=visibleNodes.value, edges=visibleEdges.value
 const n=Math.max(1,visible.length); const elements:ElementDefinition[]=[...visible.map((node,i)=>({data:{id:node.id,label:node.displayLabel.length>55?`${node.displayLabel.slice(0,52)}…`:node.displayLabel,type:node.nodeType,state:`${node.verificationState||''} ${node.publicationState||''}`},position:{x:Math.cos(i*2*Math.PI/n)*Math.max(100, n*42),y:Math.sin(i*2*Math.PI/n)*Math.max(100,n*42)}})),...edges.map(edge=>({data:{id:edge.id,source:edge.source,target:edge.target,label:edge.displayLabel||edge.relationType,relation:edge.relationType,state:`${edge.verificationState||''} ${edge.publicationState||''}`}}))]
 cy.value.elements().remove();cy.value.add(elements);cy.value.layout({name:'preset',fit:false}).run();const selectedId=selectedEdge.value?.id||selected.value?.id;if(selectedId&&cy.value.getElementById(selectedId).length)cy.value.getElementById(selectedId).select()
}
function merge(page:GraphPage,centerId?:string){graph.merge(page,centerId);notice.value=page.notice;applyGraph()}
function handleApiError(e:unknown,mode:boolean){const message=(e as Error).message;if(mode&&(/401|403|会话|权限/.test(message))){epoch++;admin.value=false;clearMode();error.value=message;void loadMeta();return}error.value=message}
async function loadMeta(){const id=++metaEpoch, mode=admin.value;try{const result=await graphApi.meta(mode);if(id===metaEpoch&&admin.value===mode)meta.value=result}catch{if(id===metaEpoch&&admin.value===mode)notice.value='全库统计暂时不可用；已加载节点和按需展开仍可使用。'}}
function clearMode(){graph.clear();results.value=[];selected.value=null;selectedEdge.value=null;searchCursor.value=null;neighborCursor.value=null;searchMore.value=false;neighborMore.value=false;expanded.value=false;meta.value=null;notice.value='';error.value='';applyGraph()}
async function search(){const requestId=++epoch;expansionSeq++;searchContext={kind:'search',query:query.value.trim()};loading.value=true;error.value='';graph.clear();results.value=[];selected.value=null;selectedEdge.value=null;searchCursor.value=null;neighborCursor.value=null;searchMore.value=false;neighborMore.value=false;expanded.value=false;applyGraph();try{const p=await graphApi.search(query.value.trim(),12,undefined,admin.value);if(requestId!==epoch)return;results.value=p.nodes;if(p.nodes[0]){graph.merge({ ...p, nodes:[p.nodes[0]], edges:[] });applyGraph()}notice.value=p.notice;searchCursor.value=p.nextCursor;searchMore.value=p.hasMore;if(p.nodes[0])void selectNode(p.nodes[0]);cy.value?.fit(undefined,45)}catch(e){if(requestId===epoch)handleApiError(e,admin.value)}finally{if(requestId===epoch)loading.value=false}}
async function selectNode(node:GraphNode,newRoot=false){epoch++;expansionSeq++;const requestId=epoch,asAdmin=admin.value;if(newRoot||!graph.nodes.has(node.id)){graph.clear();graph.merge({nodes:[node],edges:[],centerId:node.id,nextCursor:null,hasMore:false,nodeLimit:120,edgeLimit:200,view:admin.value?'admin':'public',notice:''})}applyGraph();results.value=[...results.value];selected.value=node;void router.replace({query:{...route.query,nodeId:node.id,scope:admin.value?'admin':undefined}});cy.value?.getElementById(node.id).select();selectedEdge.value=null;neighborCursor.value=null;neighborMore.value=false;neighborContext=null;expanded.value=false;focus(node.id);try{const detail=await graphApi.node(node.id,asAdmin);if(requestId===epoch&&admin.value===asAdmin&&selected.value?.id===node.id)selected.value=detail}catch(e){if(requestId===epoch)handleApiError(e,asAdmin)}if(requestId===epoch&&selected.value?.id===node.id)void expand()}
watch(()=>route.query.nodeId,async value=>{if(typeof value!=='string'||value===selected.value?.id||value.length>180||!cy.value)return;try{const node=await graphApi.node(value,admin.value);if(route.query.nodeId===value)await selectNode(node,true)}catch(e){error.value=(e as Error).message}})
function neighborOpts(cursor?:string){return {relationType:relationFilter.value||undefined,nodeType:typeFilter.value||undefined,verificationState:verifyFilter.value||undefined,publicationState:publicationFilter.value||undefined,limit:20,cursor}}
async function expand(cursor?:string){if(!selected.value)return;const id=selected.value.id,requestId=epoch,seq=++expansionSeq,mode=admin.value;neighborContext={kind:'neighbors',nodeId:id,relationType:relationFilter.value,nodeType:typeFilter.value,verificationState:verifyFilter.value,publicationState:publicationFilter.value};loading.value=true;error.value='';try{const p=await graphApi.neighbors(id,neighborOpts(cursor),mode);if(requestId!==epoch||seq!==expansionSeq||admin.value!==mode||selected.value?.id!==id)return;merge(p,id);if(!cursor)cy.value?.fit(undefined,45);neighborCursor.value=p.nextCursor;neighborMore.value=p.hasMore;expanded.value=true}catch(e){if(requestId===epoch&&seq===expansionSeq)handleApiError(e,mode)}finally{if(requestId===epoch&&seq===expansionSeq)loading.value=false}}
function moreSearch(){if(!searchCursor.value||!matchesContext(searchContext,{kind:'search',query:query.value.trim()}))return;const requestId=epoch,mode=admin.value;void graphApi.search(query.value.trim(),12,searchCursor.value,mode).then(p=>{if(requestId===epoch&&admin.value===mode){results.value=[...results.value,...p.nodes].slice(0,120);searchCursor.value=p.nextCursor;searchMore.value=p.hasMore}}).catch(e=>{if(requestId===epoch)handleApiError(e,mode)})}
function moreNeighbors(){const current:PageContext|null=selected.value?{kind:'neighbors',nodeId:selected.value.id,relationType:relationFilter.value,nodeType:typeFilter.value,verificationState:verifyFilter.value,publicationState:publicationFilter.value}:null;if(neighborCursor.value&&current&&neighborContext&&matchesContext(neighborContext,current))void expand(neighborCursor.value)}
function expandSelected(){void expand()}
function collapse(){if(!selected.value)return;expansionSeq++;graph.collapse(selected.value.id);expanded.value=false;neighborCursor.value=null;neighborMore.value=false;applyGraph()}
function focus(id:string){const el=cy.value?.getElementById(id);if(el?.length)cy.value?.animate({center:{eles:el},duration:window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:250})}
function selectEdge(edge:GraphEdge){expansionSeq++;neighborCursor.value=null;neighborMore.value=false;selectedEdge.value=edge;selected.value=null;cy.value?.elements().unselect();const el=cy.value?.getElementById(edge.id);el?.select();if(el?.length)cy.value?.animate({center:{eles:el},duration:window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:250})}
let modeChanged=false
async function toggleMode(){const requestId=++epoch;modeChanged=true;admin.value=false;clearMode();try{const s=await fetch('/api/v1/admin/session',{credentials:'include',headers:{Accept:'application/json'}});if(!s.ok)throw new Error('需要管理员会话');const data=await s.json();if(!data.roles?.some((r:string)=>['admin','role_admin'].includes(r.toLowerCase())))throw new Error('当前会话没有管理员角色');if(requestId!==epoch)return;admin.value=true;modeChanged=false;void loadMeta();if(requestId===epoch)await search()}catch(e){if(requestId===epoch){clearMode();error.value=(e as Error).message}modeChanged=false}}
async function exitAdmin(){epoch++;expansionSeq++;admin.value=false;modeChanged=false;clearMode();const id=epoch;void loadMeta();if(id===epoch)void search()}
function fit(){cy.value?.fit(undefined,45)}
function reset(){query.value='';typeFilter.value='';relationFilter.value='';verifyFilter.value='';publicationFilter.value='';graph.clear();selected.value=null;selectedEdge.value=null;applyGraph();void search()}
watch([typeFilter,relationFilter,verifyFilter,publicationFilter],()=>{selectedEdge.value=null;epoch++;expansionSeq++;neighborCursor.value=null;neighborMore.value=false;applyGraph();if(selected.value&&expanded.value){neighborCursor.value=null;neighborMore.value=false;void expand()}})
onMounted(async()=>{cy.value=cytoscape({container:graphEl.value!,elements:[],style:[{selector:'node',style:{'background-color':'#b8d1b5','border-color':'#6f9474','border-width':'1px','label':'data(label)','color':'#edf5e8','font-size':'10px','text-wrap':'wrap','text-max-width':'100px','text-valign':'bottom','text-margin-y':7,'width':25,'height':25}},{selector:'node[type="SOURCE"],node[type="FILE"]',style:{'background-color':'#d5c493','border-color':'#e3d5a7','shape':'rectangle'}},{selector:'node[type="NAME"],node[type="TAXON"],node[type="ACCEPTED_TAXON"]',style:{'background-color':'#b8d1b5','shape':'round-rectangle'}},{selector:'node[type="SAMPLE"],node[type="MEASUREMENT"],node[type="TRAIT"],node[type="MORPHOLOGY"]',style:{'background-color':'#85aaa0','shape':'diamond'}},{selector:'node[state*="PENDING"],node[state*="CANDIDATE"]',style:{'background-color':'#829b87','border-style':'dashed','border-width':2}},{selector:"edge[state*='CANDIDATE'],edge[state*='PENDING'],edge[state*='SOURCE_REPORTED']",style:{'line-style':'dashed'}},{selector:"edge[state*=\"SOURCE_PUBLIC\"]",style:{'line-color':'#9ec48b','width':2,'target-arrow-color':'#a9cb95'}},{selector:"edge[state*=\"SOURCE_REPORTED\"]",style:{'line-style':'dashed','line-color':'#c5b47b'}},{selector:"edge[state*=\"MACHINE_EXTRACTED\"]",style:{'line-style':'dotted','line-color':'#9db5be'}},{selector:'edge',style:{'width':1,'line-color':'#708877','target-arrow-color':'#9bb59b','target-arrow-shape':'triangle','curve-style':'bezier','label':'data(label)','font-size':'8px','color':'#cbd8c8','text-background-color':'#16251c','text-background-opacity':.85,'text-background-padding':'2px','text-max-width':'90px'}},{selector:':selected',style:{'overlay-color':'#a9d2ae','overlay-opacity':.18}}],layout:{name:'preset'},minZoom:.2,maxZoom:3});cy.value.on('tap','node',evt=>{const node=nodeMap.get(evt.target.id());if(node)void selectNode(node)});cy.value.on('tap','edge',evt=>{const edge=edgeMap.get(evt.target.id());if(edge)selectEdge(edge)});graphResize=new ResizeObserver(()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{const nextMobile=window.innerWidth<=700;if(mobileView.value!==nextMobile){filtersOpen.value=false;inspectorOpen.value=false}mobileView.value=nextMobile;cy.value?.resize();fit()})});if(graphEl.value)graphResize.observe(graphEl.value);const requested=route.query.nodeId||'plant:2';const wantsAdmin=route.query.scope==='admin';if(wantsAdmin){modeChanged=true;try{const s=await fetch('/api/v1/admin/session',{credentials:'include',headers:{Accept:'application/json'}});const data=s.ok?await s.json():null;if(!data?.roles?.some((r:string)=>['admin','role_admin'].includes(r.toLowerCase())))throw new Error('需要有效的管理员会话才能打开该候选图谱节点；未读取任何候选数据。');admin.value=true;modeChanged=false;void loadMeta();if(typeof requested==='string'&&requested.length>0&&requested.length<=180){const node=await graphApi.node(requested,true);results.value=[node];await selectNode(node,true)}else await search()}catch(e){admin.value=false;clearMode();error.value=(e as Error).message.includes('需要有效')?(e as Error).message:'管理员图谱节点不可用或当前会话无权访问；未读取候选数据。';modeChanged=false}return}void loadMeta();if(typeof requested==='string'&&requested.length>0&&requested.length<=180){try{const node=await graphApi.node(requested,false);results.value=[node];await selectNode(node,true)}catch(e){error.value=(e as Error).message}}else await search()})
onBeforeUnmount(()=>{epoch++;graphResize?.disconnect();cancelAnimationFrame(resizeFrame);cy.value?.destroy()})
</script>
<template>
<main class="kg-page">
  <header class="kg-heading"><div><p class="section-kicker">BOTANICAL KNOWLEDGE / GRAPH</p><h1>沿着线索，认识植物。</h1><p>看看它与哪些植物、名称和来源有关联。点击一个节点，沿着真实的线索继续探索。</p><p class="kg-crumb">{{selected?.displayLabel || selectedEdge?.displayLabel || '探索公开知识网络'}}</p></div><button v-if="account.isAdmin" class="kg-admin" @click="admin?exitAdmin():toggleMode()">{{admin?'退出管理员图谱':'管理员图谱登录'}}</button></header>
  <div class="kg-search"><input v-model="query" aria-label="搜索图谱" placeholder="搜索名称、来源或节点 ID" @keydown.enter="search"><button @click="search">搜索</button><span>{{admin?'管理员':'公开'}}节点 {{meta?Object.values(meta.nodeCounts).reduce((a,b)=>a+b,0):'—'}} · 公开事实 {{meta?.publishedFactCount??'—'}}</span></div>
  <p v-if="!admin&&meta&&!meta.nodeCounts.PLANT&&meta.publishedFactCount===0" class="kg-boundary">当前公开图谱仅含来源与文件元数据。植物目录尚未获准公开，科研候选需管理员会话查看。</p>
  <div class="kg-panel-toggles"><button id="kg-filters-toggle" :aria-expanded="filtersOpen" aria-controls="kg-filters" @click="filtersOpen=!filtersOpen;inspectorOpen=false">{{filtersOpen?'收起探索侧栏':'专业筛选与节点'}}</button><button id="kg-inspector-toggle" :aria-expanded="inspectorOpen" aria-controls="kg-inspector" @click="inspectorOpen=!inspectorOpen;filtersOpen=false">这条知识来自哪里</button></div><div class="kg-workspace" :class="{'filters-hidden':!filtersOpen}">
    <aside @keydown="drawerKeys" :role="mobileView?'dialog':undefined" :aria-modal="mobileView&&filtersOpen?true:undefined" id="kg-filters" class="kg-left-panel" :class="{'is-open':filtersOpen}" aria-label="图谱筛选和结果">
      <button class="kg-drawer-close" @click="filtersOpen=false">关闭探索侧栏</button><details open><summary>筛选范围</summary><div class="kg-filters"><label>节点类型<select v-model="typeFilter"><option value="">全部</option><option v-for="x in nodeTypes" :key="x">{{x}}</option></select></label><label>来源关系<select v-model="relationFilter"><option value="">全部关系</option><option v-for="x in relationTypes" :key="x" :value="x">{{x}}</option></select></label><label>验证/审核状态<select v-model="verifyFilter"><option value="">全部</option><option v-for="x in ['SOURCE_REPORTED','MACHINE_EXTRACTED','PENDING','HELD','APPROVED','REJECTED','NEEDS_EVIDENCE','REVOKED','VERIFIED_INTEGRITY','HASH_MATCH']" :key="x">{{x}}</option></select></label><label>发布状态<select v-model="publicationFilter"><option value="">全部</option><option v-for="x in ['METADATA_ONLY','SOURCE_PUBLIC','CANDIDATE','PUBLISHED']" :key="x">{{x}}</option></select></label></div></details>
      <details open><summary>搜索结果与节点 <span>{{visibleNodes.length}}</span></summary><div class="kg-text-results" aria-label="搜索结果"><p v-if="!loading&&!results.length&&!error">没有获准显示的匹配入口；这不代表该植物没有科研资料。</p><button v-for="n in results" :key="'result-'+n.id" @click="selectNode(n,true)">{{n.displayLabel}} · {{n.nodeType}}</button></div><div class="kg-text-results" aria-label="图谱节点"><button v-for="n in visibleNodes" :key="n.id" @click="selectNode(n)">{{n.displayLabel}} · {{n.nodeType}} · {{n.verificationState||n.publicationState||'元数据'}}</button><p v-if="!visibleNodes.length">{{notice||'暂无可显示节点。'}}</p></div><button v-if="searchMore" class="kg-more" @click="moreSearch">继续搜索结果</button></details>
    </aside>
    <section class="kg-canvas" aria-label="知识网络画布"><nav class="kg-toolbar" aria-label="画布控制"><button @click="fit">适配画布</button><button aria-label="放大" @click="cy?.zoom({level:Math.min(3,(cy?.zoom()||1)+.2),renderedPosition:{x:(cy?.width()||0)/2,y:(cy?.height()||0)/2}})">＋</button><button aria-label="缩小" @click="cy?.zoom({level:Math.max(.2,(cy?.zoom()||1)-.2),renderedPosition:{x:(cy?.width()||0)/2,y:(cy?.height()||0)/2}})">−</button><button @click="reset">重置</button><button :disabled="!selected||loading" @click="expandSelected">{{expanded?'继续展开':'展开所选'}}</button><button :disabled="!selected||!neighborMore" @click="moreNeighbors">继续关系</button><button :disabled="!selected||!expanded" @click="collapse">收起分支</button></nav><div class="kg-path">{{selected?.displayLabel||selectedEdge?.displayLabel||'选择一个节点或关系'}}</div><div ref="graphEl" class="kg-graph" aria-label="可交互知识图谱；下方提供可访问的节点与关系列表"></div><div class="kg-legend" role="group" aria-label="图谱状态图例"><span><i class="kg-legend-node kg-legend-source"></i>来源 / 文件</span><span><i class="kg-legend-node"></i>植物名称</span><span><i class="kg-legend-node kg-legend-sample"></i>样本 / 测量</span><span><i class="kg-legend-line kg-legend-public"></i>公开关联</span><span><i class="kg-legend-line kg-legend-reported"></i>来源记载</span><span><i class="kg-legend-line kg-legend-machine"></i>机器提取</span><span><i class="kg-legend-line kg-legend-pending"></i>候选 / 待核验</span></div><details class="kg-accessible-list"><summary>文本节点与关系替代视图</summary><div class="kg-text-results" aria-label="关系列表"><p v-if="expanded&&!visibleEdges.length">当前筛选下暂无关系。证据不足与数值为零、关系不存在具有不同含义。</p><button v-for="e in visibleEdges" :key="e.id" @click="selectEdge(e)">{{nodeMap.get(e.source)?.displayLabel||e.source}} — {{e.displayLabel||e.relationType}} → {{nodeMap.get(e.target)?.displayLabel||e.target}} · {{e.verificationState||'—'}} / {{e.publicationState||'—'}}</button></div></details></section>
    <aside @keydown="drawerKeys" :role="mobileView?'dialog':undefined" :aria-modal="mobileView&&inspectorOpen?true:undefined" id="kg-inspector" class="kg-detail" :class="{'is-open':inspectorOpen}" aria-label="节点检查器"><button class="kg-drawer-close" @click="inspectorOpen=false">关闭检查器</button><p class="section-kicker">NODE / EVIDENCE INSPECTOR</p><template v-if="selectedEdge"><p class="kg-state">{{selectedEdge.relationType}} / {{selectedEdge.id}}</p><h2>{{selectedEdge.displayLabel||selectedEdge.relationType}}</h2><div class="kg-status-row"><StatusIndicator :state="selectedEdge.verificationState"/><StatusIndicator :state="selectedEdge.publicationState"/></div><details v-for="(ref,i) in selectedEdge.sourceReference||[]" :key="i" class="kg-source"><summary>{{ref.displayLabel}} · 来源 {{ref.sourceId}}</summary><span>版本 {{ref.version||'未提供'}} · SHA256 {{ref.sha256||'未提供'}} · 许可 {{ref.licenseState||'未提供'}}</span><pre>{{JSON.stringify(ref.locator||{},null,2)}}</pre></details></template><template v-else-if="selected"><p class="kg-state">{{selected?.nodeType}} / {{selected?.id}}</p><h2>{{selected?.displayLabel}}</h2><div class="kg-status-row"><StatusIndicator :state="selected?.verificationState"/><StatusIndicator :state="selected?.publicationState"/></div><details><summary>查看原始属性与记录状态</summary><dl><template v-for="(value,key) in selected?.attributes" :key="key"><dt>{{key}}</dt><dd>{{typeof value==='object'?JSON.stringify(value):String(value)}}</dd></template></dl></details><details v-for="(ref,i) in selected?.sourceReference||[]" :key="i" class="kg-source"><summary>{{ref.displayLabel}} · 来源 {{ref.sourceId}}</summary><span>版本 {{ref.version||'未提供'}} · 许可 {{ref.licenseState||'未提供'}} · SHA256 {{ref.sha256||'未提供'}}</span><pre>{{JSON.stringify(ref.locator||{},null,2)}}</pre></details><RouterLink v-if="admin&&typeof selected?.attributes?.reviewUrl==='string'" class="kg-review" :to="String(selected?.attributes.reviewUrl)">在审核台查看候选 →</RouterLink><RouterLink v-if="selected?.nodeType==='PLANT'&&/^plant:\d+$/.test(selected?.id)" class="kg-review" :to="`/plants/${selected?.id.slice(6)}${admin?'?scope=admin':''}`">打开植物详情 →</RouterLink><RouterLink v-if="selected?.nodeType==='PLANT'&&/^plant:\d+$/.test(selected?.id)" class="kg-review" :to="{path:'/workbench',query:{plantId:selected?.id.slice(6),scope:admin?'admin':undefined}}">在科研实验台查看 →</RouterLink><RouterLink v-for="ref in scientificReferences" :key="'wb-'+ref.sourceId" class="kg-review" :to="{path:'/workbench',query:{sourceId:String(ref.sourceId),scope:admin?'admin':undefined}}">筛选来源 {{ref.sourceId}} →</RouterLink></template><p v-else class="kg-empty">选择节点查看类型、状态、原始属性与来源定位。</p></aside>
  </div><p v-if="loading" class="kg-message" role="status">读取图谱…</p><p v-if="graph.limitReached" class="kg-error" role="status">已达到前端图谱上限（120 节点 / 200 关系），请收起分支或重置视图。</p><p v-if="error" class="kg-error" role="alert">{{error}}</p><p class="kg-note">{{notice||meta?.notice}} · HASH_MATCH 仅表示元数据摘要相等，不代表科学事实已发布。</p>
</main>
</template>
